// chain.ts — widen Result with a `kind` field at the exact point each
// failure is already known, instead of leaving it to be guessed later
type ChainError =
  | { ok: false; kind: "invalid_input"; error: string }
  | { ok: false; kind: "upstream_failure"; error: string };

type Result<T> = { ok: true; value: T } | ChainError;

export async function getChainSnapshot(address: string): Promise<Result<{
  blockNumber: number;
  address: Address;
  balanceEth: string;
}>> {
  if (!isAddress(address)) {
    return { ok: false, kind: "invalid_input", error: `"${address}" is not a valid address` };
  }
  try {
    const [blockNumber, balance] = await Promise.all([
      provider.getBlockNumber(),
      provider.getBalance(address),
    ]);
    return {
      ok: true,
      value: { blockNumber, address: address as Address, balanceEth: formatEther(balance) },
    };
  } catch (e) {
    return {
      ok: false,
      kind: "upstream_failure",
      error: e instanceof Error ? e.message : "Unknown error",
    };
  }
}
