// server.ts — the stretch goal: GET /balance/:address
import express from "express";
import { getChainSnapshot } from "./chain.js";

const app = express();
const PORT = process.env.PORT || 3000;

app.get("/balance/:address", async (req, res) => {
  const result = await getChainSnapshot(req.params.address);

  if (result.ok) {
    return res.status(200).json(result.value);
  }

  // No throw, no middleware -- a direct, typed mapping to a status code.
  const status = result.kind === "invalid_input" ? 400 : 502;
  res.status(status).json({ error: result.error });
});

app.listen(PORT, () => {
  console.log(`chain-reader API listening on port ${PORT}`);
});
