// chain.ts — resilient read, same external Result<T> contract
import { JsonRpcProvider } from "ethers";

const PRIMARY_RPC_URL = env.RPC_URL;
const FALLBACK_RPC_URL = env.FALLBACK_RPC_URL; // a second, independent endpoint

const TIMEOUT_MS = 5_000;
const MAX_RETRIES = 3;

function withTimeout<T>(promise: Promise<T>, ms: number): Promise<T> {
  const timeout = new Promise<never>((_, reject) =>
    setTimeout(() => reject(new Error(`Timed out after ${ms}ms`)), ms)
  );
  return Promise.race([promise, timeout]);
}

async function withRetries<T>(fn: () => Promise<T>, maxRetries: number): Promise<T> {
  let lastError: unknown;
  for (let attempt = 0; attempt <= maxRetries; attempt++) {
    try {
      return await withTimeout(fn(), TIMEOUT_MS);
    } catch (err) {
      lastError = err;
      if (attempt < maxRetries) {
        const backoffMs = 250 * 2 ** attempt; // 250ms, 500ms, 1000ms
        await new Promise((resolve) => setTimeout(resolve, backoffMs));
      }
    }
  }
  throw lastError;
}

async function readWithFallback<T>(
  readFn: (provider: JsonRpcProvider) => Promise<T>
): Promise<T> {
  const primary = new JsonRpcProvider(PRIMARY_RPC_URL);
  try {
    return await withRetries(() => readFn(primary), MAX_RETRIES);
  } catch {
    // Primary endpoint exhausted its retries -- try the fallback once,
    // without its own retry loop, since this is already the last resort.
    const fallback = new JsonRpcProvider(FALLBACK_RPC_URL);
    return readFn(fallback);
  }
}

export async function getChainSnapshot(address: string): Promise<Result<{
  blockNumber: number;
  address: Address;
  balanceEth: string;
}>> {
  if (!isAddress(address)) {
    return { ok: false, kind: "invalid_input", error: `"${address}" is not a valid address` };
  }
  try {
    const [blockNumber, balance] = await Promise.all([
      readWithFallback((p) => p.getBlockNumber()),
      readWithFallback((p) => p.getBalance(address)),
    ]);
    return {
      ok: true,
      value: { blockNumber, address: address as Address, balanceEth: formatEther(balance) },
    };
  } catch (e) {
    return {
      ok: false,
      kind: "upstream_failure",
      error: e instanceof Error ? e.message : "Unknown error",
    };
  }
}
